package com.bank.palindromecount;

import java.util.logging.Logger;

// Counts palindromic substrings for National Bank of India pattern scoring.
public class PalindromeCounter {
    private static final Logger log = Logger.getLogger(PalindromeCounter.class.getName());

    // Count all palindromic substrings via expand-around-center. O(n^2), O(1).
    public int countPalindromes(String s) {
        if (s == null || s.isEmpty()) {
            return 0;
        }
        int count = 0;
        for (int i = 0; i < s.length(); i++) {
            count += expand(s, i, i);        // odd-length centers
            count += expand(s, i, i + 1);    // even-length centers
        }
        final int result = count;
        log.info(() -> "Palindromic substrings = " + result);
        return count;
    }

    // Count palindromes centered here = number of matching outward steps.
    private int expand(String s, int left, int right) {
        int found = 0;
        while (left >= 0 && right < s.length() && s.charAt(left) == s.charAt(right)) {
            found++;                         // substring [left..right] is a palindrome
            left--;
            right++;
        }
        return found;
    }
}
