package com.bank.palindromecount;

import java.util.logging.ConsoleHandler;
import java.util.logging.Logger;

// Runnable demo: count palindromic substrings.
public class PalindromeCounterDemo {
    private static final Logger log = Logger.getLogger(PalindromeCounterDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
    }

    public static void main(String[] args) {
        PalindromeCounter counter = new PalindromeCounter();

        log.info(() -> "Count = " + counter.countPalindromes("abc"));   // 3
        log.info(() -> "Count = " + counter.countPalindromes("aaa"));   // 6
    }
}
